template<class T> void f(T x, T y = ydef(T()), T z = zdef(T()));
// Implementation notes: 
// - 'ydef(T())' and 'zdef(T())' are default arguments that depend on T.
// - The compiler instantiates these expressions for each T, requiring ydef and zdef to be resolvable in the instantiation context.
// - If ydef or zdef are not defined for T, instantiation fails at compile-time.
class A { };
// A simple class for instantiation.
A zdef(A a) { return a; } // Non-template function; for T = A, zdef(T()) uses this.
void g(A a, A b, A c) { /* Function body */ } // Example of a non-template function for comparison.
